import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useLocation } from 'react-router-dom';
import './Home.css';

const Home = () => {
  const location = useLocation();
  const { accessToken } = location.state || {};
  const [orgInfo, setOrgInfo] = useState(null);

  useEffect(() => {
    const fetchOrgInfo = async () => {
      try {
        console.log('Using Access Token:', accessToken);
        const response = await axios.get('http://localhost:3001/salesforce/org-info', {
          params: { accessToken },
        });
        console.log('Fetched Org Info:', response.data);
        setOrgInfo(response.data);
      } catch (error) {
        console.error('Error fetching org information:', error);
      }
    };

    if (accessToken) {
      fetchOrgInfo();
    }
  }, [accessToken]);

  if (!orgInfo) {
    return <div className="loading">Loading...</div>;
  }

  return (
    <div className="home-page">
      <h1>Salesforce Org Information</h1>
      <pre>{JSON.stringify(orgInfo, null, 2)}</pre>
    </div>
  );
};

export default Home;
